"""Print sales totals by region from a JSON file of {region, amount} rows."""
import argparse
import json


def load(path):
    with open(path) as file:
        return json.load(file)


def totals(rows):
    """Return (region, total) pairs sorted by region."""
    sums = {}
    for row in rows:
        sums[row["region"]] = sums.get(row["region"], 0) + row["amount"]
    return sorted(sums.items())


def render_text(pairs):
    return "\n".join(f"{region}: {total}" for region, total in pairs)


def render_csv(pairs):
    return "\n".join(["region,total"] + [f"{region},{total}" for region, total in pairs])


def main(argv=None):
    parser = argparse.ArgumentParser(prog="report", description="Sales totals by region.")
    parser.add_argument("path", help="a JSON file of {region, amount} rows")
    parser.add_argument("--format", choices=["text", "csv"], default="text", help="output format")
    args = parser.parse_args(argv)
    render = render_csv if args.format == "csv" else render_text
    print(render(totals(load(args.path))))


if __name__ == "__main__":
    main()

import unittest

from report import render_csv


class CsvTest(unittest.TestCase):
    def test_csv_has_a_header_and_one_line_per_region(self):
        self.assertEqual(render_csv([("a", 1), ("b", 5)]), "region,total\na,1\nb,5")
